#!/bin/bash
# The whole forest on a local chain (anvil, Osaka): deploys the tree holders and the `Ensemble`
# generated by tools/gen_trees.py, checks its answers against the reference and measures one whole
# evaluation as a real transaction. The tree counterpart of tools/network_gas.sh.
#
#   - `classify` of the first <samples> reference inputs (eth_call) must equal pred.bin;
#   - `trace` of sample 0 (eth_call) must equal trace.jsonl: every tree's output, every score;
#   - `classify` of samples 0 and 6 is then estimated and mined, and its gas recorded.
#
# usage: ensemble_gas.sh <fe-out-dir> <ref-dir> <forest.json> [record.json] [port] [samples]
export PATH="$HOME/.fe/bin:$HOME/.foundry/bin:$PATH"
root="$(cd "$(dirname "$0")/.." && pwd)"
if [ $# -lt 3 ] || [ ! -f "$1/Ensemble.bin" ]; then
  echo "usage: ensemble_gas.sh <fe-out-dir> <ref-dir> <forest.json> [record.json] [port] [samples]" >&2
  exit 2
fi
out="$1"
ref="$2"
forest="$3"
record="$4"
port="${5:-18632}"
samples="${6:-20}"
rpc="http://127.0.0.1:$port"
key=0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80
me=0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266
rows="$(mktemp)"
anvil --hardfork osaka --port $port > /dev/null 2>&1 &
anvil_pid=$!
trap 'kill $anvil_pid 2> /dev/null; rm -f "$rows"' EXIT
sleep 2
failures=0
args() { python3 "$root/tools/trees_args.py" --ref "$ref" --forest "$forest" "$@"; }

deploy() {
  cast send --rpc-url $rpc --private-key $key --create "$1" --json \
    | python3 -c 'import json, sys; print(json.load(sys.stdin)["contractAddress"])'
}
size_of() {
  echo $(( ($(cast code --rpc-url $rpc "$1" | wc -c) - 3) / 2 ))
}

holders=()
types=()
sizes=""
i=0
while [ -f "$out/Trees$i.bin" ]; do
  address=$(deploy "0x$(cat "$out/Trees$i.bin")")
  holders+=("$address")
  types+=("address")
  sizes="$sizes $(size_of "$address")"
  i=$((i + 1))
done
ctor=$(cast abi-encode "constructor($(IFS=,; echo "${types[*]}"))" "${holders[@]}")
ensemble=$(deploy "0x$(cat "$out/Ensemble.bin")${ctor#0x}")
ensemble_size=$(size_of "$ensemble")
echo "Ensemble at $ensemble ($ensemble_size bytes deployed), ${#holders[@]} tree holders ($sizes bytes)"

classify_sig="$(args signature ensemble)"
words=$(python3 -c 'import json, sys; print(json.load(open(sys.argv[1]))["shape"]["input_words"])' "$forest")
wrong=0
for n in $(seq 0 $((samples - 1))); do
  got=$(cast call --rpc-url $rpc "$ensemble" "$classify_sig(uint256)" "$(args --sample $n x0)" | cut -d' ' -f1)
  want=$(python3 -c 'import sys; print(open(sys.argv[1], "rb").read()[int(sys.argv[2])])' "$ref/pred.bin" $n)
  if [ "$got" != "$want" ]; then
    echo "WRONG: classify of sample $n is $got, the reference says $want"
    wrong=$((wrong + 1))
  fi
done
echo "classify: $samples samples against pred.bin, $wrong mismatches"
failures=$((failures + wrong))

raw=$(cast call --rpc-url $rpc "$ensemble" "trace(uint256[$words])" "$(args x0)")
if python3 - "$root" "$ref" "$raw" <<'EOF'
import json, sys
sys.path.insert(0, sys.argv[1] + "/tools")
import trees_ref as ref
trace = json.loads(open(sys.argv[2] + "/trace.jsonl", encoding="utf-8").readline())
expected = b"".join(w.to_bytes(32, "big") for w in ref.outputs_words(trace["outputs"]))
for score in trace["scores"]:
    expected += (score % (1 << 256)).to_bytes(32, "big")
got = bytes.fromhex(sys.argv[3].strip()[2:])
if got != expected:
    print("WRONG: trace of sample 0 differs from trace.jsonl")
    sys.exit(1)
print("trace: sample 0 equals trace.jsonl (%d tree outputs, %d scores)"
      % (len(trace["outputs"]), len(trace["scores"])))
EOF
then :; else failures=$((failures + 1)); fi

for n in 0 6; do
  x0="$(args --sample $n x0)"
  estimate=$(cast estimate --rpc-url $rpc --from $me "$ensemble" "$classify_sig" "$x0" 2>&1 | head -1)
  calldata=$(cast calldata "$classify_sig" "$x0")
  used=$(cast send --rpc-url $rpc --private-key $key "$ensemble" "$classify_sig" "$x0" --json \
    | python3 -c 'import json, sys; print(int(json.load(sys.stdin)["gasUsed"], 16))')
  execution=$(python3 "$root/tools/execution_gas.py" "$calldata" "$used")
  bytes=$(( (${#calldata} - 2) / 2 ))
  printf '%-30s %9s %9s %9s %6d bytes of calldata\n' "Ensemble.classify (sample $n)" "$estimate" "$used" "$execution" $bytes
  echo "$n|$estimate|$used|$execution|$bytes" >> "$rows"
done
echo "ensemble_gas: $failures wrong result(s)"
if [ -n "$record" ] && [ $failures -eq 0 ]; then
  python3 - "$rows" "$record" "$ref/model.json" "$ensemble_size" "$samples" "$(fe --version)" $sizes <<'EOF'
import json, sys
rows_path, record_path, model_path, ensemble_size, samples, fe_version = sys.argv[1:7]
model = json.load(open(model_path, encoding="utf-8"))
runs = []
for line in open(rows_path, encoding="utf-8"):
    n, estimate, used, execution, size = line.strip().split("|")
    runs.append({"sample": int(n), "estimate": int(estimate), "gas_used": int(used),
                 "execution": int(execution), "calldata_bytes": int(size)})
record = {"model": model["name"], "fe": fe_version, "chain": "anvil, Osaka", "classify": runs,
          "classify_samples_checked": int(samples), "ensemble_deployed_bytes": int(ensemble_size),
          "holder_bytes": [int(v) for v in sys.argv[7:]]}
with open(record_path, "w", encoding="utf-8", newline="\n") as f:
    json.dump(record, f, indent=1)
    f.write("\n")
EOF
fi
[ $failures -eq 0 ]
